// @name To-do
// @background #f1f5f9
// @refresh 3600
// A to-do list for a touch screen. Tap a circle to tick a to-do off, its text
// to edit it (the keyboard comes up), the bin to delete it (it asks first),
// and add your own at the bottom. The list scrolls, and it is kept.
const SAMPLE = [
  { text: 'Water the plants', done: true },
  { text: 'Call grandma about Sunday', done: false },
  { text: 'Book the dentist', done: false },
  { text: 'Oat milk, coffee beans, lemons', done: false },
  { text: 'Take the recycling out', done: false },
  { text: 'Fix the bike light', done: false },
]

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-slate-100 text-slate-800',
    muted: 'text-slate-500',
    card: 'bg-white',
    track: 'bg-slate-200',
    fill: 'bg-emerald-500',
    box: 'border-2 border-slate-300',
    boxOn: 'bg-emerald-500',
    doneText: 'text-slate-400',
    field: 'bg-white focus:bg-sky-50',
    add: 'bg-sky-600 text-white active:bg-sky-700',
    cancel: 'bg-slate-200 text-slate-700 active:bg-slate-300',
    remove: 'bg-rose-600 text-white active:bg-rose-700',
    bin: 'text-slate-400',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    box: 'border-4 border-black',
    boxOn: 'bg-black',
    doneText: 'text-black',
    field: 'bg-white',
    add: 'bg-black text-white',
    cancel: 'bg-white text-black border-2 border-black',
    remove: 'bg-black text-white',
    bin: 'text-black',
  },
}

// The list itself: scene state, kept on disk (the `todos` field), so it
// outlasts a restart. The first version kept only which samples were ticked.
const load = (app) => {
  const kept = app.state.todos
  if (Array.isArray(kept)) return kept
  const ticked = frameos.recall('done')
  return SAMPLE.map((item, i) => ({ text: item.text, done: Array.isArray(ticked) ? !!ticked[i] : item.done }))
}
const save = (todos) => frameos.setState('todos', todos)

const Check = () => (
  <svg className="w-5 h-5 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

const Bin = ({ className }) => (
  <svg className={`w-6 h-6 ${className}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3" />
  </svg>
)

export function get(app) {
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const todos = load(app)
  // What is typed into the new to-do and which row asks to be deleted: the
  // app's own, kept between renders (an ESP32 starts each with a fresh module).
  const draft = frameos.recall('draft') || ''
  const asking = frameos.recall('asking') ?? -1
  const count = todos.filter((item) => item.done).length
  const change = (i, item) => save(todos.map((other, j) => (j === i ? item : other)))
  const add = () => {
    const text = (frameos.recall('draft') || '').trim()
    if (!text) return
    save([...todos, { text, done: false }])
    frameos.remember('draft', '')
  }
  return (
    <div className={`flex flex-col w-full h-full gap-3 p-6 ${t.page}`}>
      <div className="flex items-end justify-between">
        <span className="text-4xl font-bold">Today</span>
        <span className={`text-lg ${t.muted}`}>
          {todos.length ? `${count} of ${todos.length} done` : 'Nothing to do'}
        </span>
      </div>
      <div className={`h-3 rounded-full ${t.track}`}>
        <div className={`h-full rounded-full ${t.fill} w-[${todos.length ? (count * 100) / todos.length : 0}%]`} />
      </div>
      <div className="flex-1 overflow-y-auto">
        <div className="flex flex-col gap-2">
          {todos.map((item, i) =>
            asking === i ? (
              <div className={`flex items-center gap-3 rounded-2xl px-4 py-3 ${t.card}`}>
                <span className="flex-1 text-lg truncate">{`Delete "${item.text}"?`}</span>
                <div className={`px-4 py-2 rounded-xl text-lg ${t.cancel}`} onClick={() => frameos.remember('asking', -1)}>
                  Cancel
                </div>
                <div className={`px-4 py-2 rounded-xl text-lg font-bold ${t.remove}`}
                  onClick={() => { save(todos.filter((_, j) => j !== i)); frameos.remember('asking', -1) }}>
                  Delete
                </div>
              </div>
            ) : (
              <div className={`flex items-center gap-3 rounded-2xl pl-4 pr-2 py-2 ${t.card}`}>
                <div className={`w-8 h-8 shrink-0 rounded-full flex items-center justify-center ${item.done ? t.boxOn : t.box}`}
                  onClick={() => change(i, { ...item, done: !item.done })}>
                  {item.done ? <Check /> : null}
                </div>
                <input className={`flex-1 h-11 px-2 rounded-lg text-lg ${t.field} ${item.done ? t.doneText : ''}`}
                  value={item.text}
                  onChange={(e) => change(i, { ...item, text: e.target.value })} />
                <div className="w-11 h-11 shrink-0 flex items-center justify-center rounded-xl"
                  onClick={() => frameos.remember('asking', i)}>
                  <Bin className={t.bin} />
                </div>
              </div>
            ),
          )}
        </div>
      </div>
      <div className="flex items-center gap-3">
        <input className={`flex-1 h-12 px-4 rounded-xl text-lg ${t.card} ${t.field}`}
          value={draft} placeholder="Add a to-do"
          onChange={(e) => frameos.remember('draft', e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') add() }} />
        <div className={`h-12 px-5 rounded-xl flex items-center text-lg font-bold ${t.add}`} onClick={add}>
          Add
        </div>
      </div>
    </div>
  )
}
